  "question": {
    "text": "这件事里，最让你介意的是什么？",
    "target": "interpretation",
    "evidenceIds": [
      "u1",
      "u2"
    ]
  },
  "claims": [],
  "finish": false,
  "title": "临时多浇两次里的猜测与边界"
}

